import GlobalStyle from './styles/GlobalStyle';
import ToDoList from './Components/ToDoList';
import RecoilStorageSync from './RecoilStorageSync';
import styled from 'styled-components';
import { useRecoilState } from 'recoil';
import { isDarkState } from './atoms/themeAtom';

const ThemeButton = styled.button`
	background-color: transparent;
`;

const MaterialSymbol = styled.span`
  font-family: 'Material Symbols Outlined';
  font-variation-settings: 'FILL' 0, 'wght' 400, 'GRAD' 0, 'opsz' 24;
  font-size: 24px;
  color: ${({ theme }) => theme.textColors.normal};
`;


function App() {
	const [isDark, setIsDark] = useRecoilState<boolean>(isDarkState);
	const onThemeToggleClick = () => {
		console.log(isDark)
		setIsDark((prev) => !prev)
	}

  return (
		<>
			<GlobalStyle/>
			<RecoilStorageSync/>
			<ToDoList/>
			<ThemeButton onClick={onThemeToggleClick}>
				{/* {isDark ? "dark" : "light"} */}

				<MaterialSymbol>
					dark_mode
				</MaterialSymbol>
			</ThemeButton>
		</>
	);
}

export default App;
